files.patch:
@@ -145,7 +145,7 @@

 my %warnings_extended = (
     'COPYRIGHTYEAR'    => 'copyright year incorrect',
-    'PRINTFZ'          => '%zd or %zu printf mask detected',
+    'PRINTFZ'          => '%zd, %zu or %zx printf mask detected',
     'STDERR'           => 'stderr detected',
     );

@@ -1021,12 +1021,12 @@ sub scanfile {
         }
         $l = $bl; # restore to pre-bannedfunc content

-        if($warnings{"PRINTFZ"} && $l =~ /^(.*".*)%z[du].*"/) {
+        if($warnings{"PRINTFZ"} && $l =~ /^(.*".*)%z[dux].*"/) {
             # %z format support is missing from VS2013 and earlier CRT printf,
             # so directories where we call printf functions may ban %z.
             checkwarn("PRINTFZ",
                       $line, length($1), $file, $ol,
-                      "use of %zd/%zu is banned (use %ld/%lu with cast instead)");
+                      "use of %zd/%zu/%zx is banned (use %ld/%lu/%lx with cast instead)");
         }

         if($warnings{"STDERR"}) {

@@ -222,10 +222,10 @@ void startfunc(int a, int b) {
 ./%LOGDIR/code%TESTNUMBER.c:61:5: warning: use of sprintf is banned (BANNEDFUNC)
   if(sprintf(buffer, "%s", moo)) {}
      ^
-./%LOGDIR/code%TESTNUMBER.c:63:49: warning: use of %zd/%zu is banned (use %ld/%lu with cast instead) (PRINTFZ)
+./%LOGDIR/code%TESTNUMBER.c:63:49: warning: use of %zd/%zu/%zx is banned (use %ld/%lu/%lx with cast instead) (PRINTFZ)
   if(printf(buffer, "banned mask in CRT printf: |%zu|", moo)) {}
                                                  ^
-./%LOGDIR/code%TESTNUMBER.c:64:49: warning: use of %zd/%zu is banned (use %ld/%lu with cast instead) (PRINTFZ)
+./%LOGDIR/code%TESTNUMBER.c:64:49: warning: use of %zd/%zu/%zx is banned (use %ld/%lu/%lx with cast instead) (PRINTFZ)
   const char *msg = "banned mask in CRT fprintf: %zd";
                                                  ^
 ./%LOGDIR/code%TESTNUMBER.c:65:25: warning: use of alsobad is banned (BANNEDFUNC)
